package com.pharmacy.controller;
import com.pharmacy.enums.UserRole;import com.pharmacy.exception.GlobalExceptionHandler;import com.pharmacy.security.AuthenticatedUser;import com.pharmacy.service.AddressService;import org.junit.jupiter.api.*;import org.springframework.http.MediaType;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.util.List;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class UserAddressControllerTest {private AddressService service;private MockMvc mvc;@BeforeEach void setup(){service=mock(AddressService.class);mvc=MockMvcBuilders.standaloneSetup(new UserAddressController(service)).setControllerAdvice(new GlobalExceptionHandler()).build();AuthenticatedUser u=new AuthenticatedUser(7L,"u","U",UserRole.USER);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}@Test void list()throws Exception{when(service.list(7L)).thenReturn(List.of());mvc.perform(get("/api/user/addresses")).andExpect(status().isOk());}@Test void add()throws Exception{String b="{\"receiverName\":\"张三\",\"receiverPhone\":\"13900000000\",\"detailAddress\":\"测试街道 1 号\",\"isDefault\":1}";mvc.perform(post("/api/user/addresses").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isOk());verify(service).add(eq(7L),any());}@Test void deleteOwnedRoute()throws Exception{mvc.perform(delete("/api/user/addresses/8")).andExpect(status().isOk());verify(service).remove(7L,8L);}}
